-- Reverse 000122: remove the eleven rules and give the six changed rows the
-- description and conditions they had before. The flag a user can edit on a
-- built-in is never written.

DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade verified web server TLS key reads';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade web server key reads in certbot reloads';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade verified systemd-networkd sockets and BPF';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade debconf account database reads in package runs';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade dracut root account read';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade needrestart process environment reads';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade needrestart hook environment reads';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade pg_ctlcluster account database read at start';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade PostgreSQL server key read at start';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade dpkg-deb control extraction chown';
DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade dracut initramfs copy chown';
UPDATE trace_detection_rules SET description = 'sshd loads its own host keys on every connection. Reading /etc/ssh/* is the daemon doing its job. Only for a root process the agent verified as the sshd host binary.', conditions = '[{"field":"comm","op":"eq","value":"sshd"},{"field":"parent_comm","op":"eq","value":"sshd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"filename","op":"starts_with","value":"/etc/ssh/"},{"field":"uid","op":"eq","value":0},{"field":"exe_verified","op":"eq","value":true},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb WHERE built_in = true AND name = 'Downgrade sshd host key reads';
UPDATE trace_detection_rules SET description = 'systemctl, the systemd environment generator, needrestart and cloud-id read PID 1''s environment (/proc/1/environ) at login, motd refresh or package runs. Read-only opens by these names are kept at MEDIUM and tagged; any other reader keeps its severity.', conditions = '[{"field":"comm","op":"in","value":["systemctl","30-systemd-envi","needrestart","cloud-id","systemd-detect-"]},{"field":"filename","op":"eq","value":"/proc/1/environ"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb WHERE built_in = true AND name = 'Downgrade PID 1 environment reads by system tools';
UPDATE trace_detection_rules SET description = 'systemd (PID 1) loads cgroup BPF programs (device policy, IP accounting and firewalling) whenever it starts a unit, including every user session. Only for a process the kernel saw as PID 1 or in the agent-verified protected set.', conditions = '[{"field":"comm","op":"eq","value":"systemd"},{"field":"event_name","op":"eq","value":"bpf"},{"field":"exe_verified","op":"eq","value":true}]'::jsonb WHERE built_in = true AND name = 'Downgrade verified systemd BPF programs';
UPDATE trace_detection_rules SET description = 'dockerd and containerd set root ownership on the container state they keep under /var/lib/docker and /var/lib/containerd. Changing a file''s owner to root needs root already. Only for a process the kernel saw in the agent-verified protected set; a process merely named dockerd keeps HIGH.', conditions = '[{"field":"event_name","op":"eq","value":"chown"},{"field":"comm","op":"in","value":["dockerd","containerd"]},{"field":"detail","op":"eq","value":0},{"field":"filename","op":"starts_with_any","value":["/var/lib/docker/","/var/lib/containerd/"]},{"field":"exe_verified","op":"eq","value":true}]'::jsonb WHERE built_in = true AND name = 'Downgrade verified container daemon chown';
UPDATE trace_detection_rules SET description = 'containerd and dockerd unpack image layers and mount container filesystems under /var/lib/containerd and /var/lib/docker, setting modes and mounting overlay layers there. Only for a process the kernel saw in the agent-verified protected set; a process merely named containerd keeps HIGH.', conditions = '[{"field":"event_name","op":"in","value":["chmod","mount"]},{"field":"comm","op":"in","value":["dockerd","containerd"]},{"field":"filename","op":"starts_with_any","value":["/var/lib/docker/","/var/lib/containerd/"]},{"field":"exe_verified","op":"eq","value":true}]'::jsonb WHERE built_in = true AND name = 'Downgrade verified container daemon state changes';
UPDATE trace_detection_rules SET description = 'dockerd and containerd mount the overlay filesystem of a container and bind its namespace files from /proc (the network namespace under /run/docker/netns). Only for a process the kernel saw in the agent-verified protected set; a process merely named dockerd keeps HIGH.', conditions = '[{"field":"event_name","op":"eq","value":"mount"},{"field":"comm","op":"in","value":["dockerd","containerd"]},{"field":"filename","op":"starts_with_any","value":["overlay","/proc/"]},{"field":"exe_verified","op":"eq","value":true}]'::jsonb WHERE built_in = true AND name = 'Downgrade verified container daemon overlay and namespace mounts';
